// GENERATED by tools/embed_sprites.py from Assets/sprites/*.png: 2D Pepe state sprites for the Live Activity /
// Dynamic Island (and anything else that wants a 2D Pepe). Missing states fall back to an SF Symbol (PepeSprite.swift).
import UIKit

enum EmbeddedSprites {
    static let states: [String] = []
    static func image(_ state: String) -> UIImage? {
        guard let b64 = data[state], let d = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: d)
    }
    private static let data: [String: String] = [:]
}
